<?php
require __DIR__.'/../app/bootstrap.php';require_once __DIR__.'/../app/local_deals_loyalty_v1050.php';
try{if(sk1050_table('local_deals_v1050'))db()->exec("UPDATE local_deals_v1050 SET status='expired',updated_at=NOW() WHERE status='active' AND ends_at<NOW()");if(sk1050_table('local_deal_claims_v1050'))db()->exec("UPDATE local_deal_claims_v1050 SET status='expired' WHERE status='saved' AND expires_at<NOW()");
if(sk1050_table('growth_notifications_v1020')&&sk1050_on('expiry_alerts_enabled')){db()->exec("INSERT INTO growth_notifications_v1020(tenant_id,user_id,notification_type,title,body,url,is_read,created_at) SELECT c.tenant_id,c.user_id,'deal_expiry',CONCAT('Deal expiring: ',d.title),CONCAT('Your saved coupon expires on ',DATE_FORMAT(d.ends_at,'%d %b %Y'),'.'),'/my-wallet-v1050.php',0,NOW() FROM local_deal_claims_v1050 c JOIN local_deals_v1050 d ON d.id=c.deal_id LEFT JOIN growth_notifications_v1020 n ON n.tenant_id=c.tenant_id AND n.user_id=c.user_id AND n.notification_type='deal_expiry' AND n.url='/my-wallet-v1050.php' AND DATE(n.created_at)=CURDATE() WHERE c.status='saved' AND d.ends_at BETWEEN NOW() AND DATE_ADD(NOW(),INTERVAL 24 HOUR) AND n.id IS NULL");}
echo "v10.5.0 deal expiry maintenance complete\n";}catch(Throwable $e){fwrite(STDERR,$e->getMessage()."\n");exit(1);}
